window.ACADEMY_DATA={"version":"2.0.0","updated":"2026-11-13","program":"Real Estate Administration & Operations","modules":[{"id":"m1","name":"Your role & the operating system","description":"Understand the Admin desk, the company platforms, and where your authority begins and ends.","number":"01","category":"Orientation"},{"id":"m2","name":"Dubai real estate fundamentals","description":"Learn the documents and terminology behind accurate property records.","number":"02","category":"Foundation"},{"id":"m3","name":"Property listings in practice","description":"Create and maintain sale and rental listings, with recorded walkthroughs to follow.","number":"03","category":"Listings"},{"id":"m4","name":"Contracts, permits & representations","description":"Learn which document is needed, how the workflow connects, and what requires authorization.","number":"04","category":"Compliance"},{"id":"m5","name":"Property Finder & portal operations","description":"Complete PF Academy, then apply REMAX procedures for quality, leads and support.","number":"05","category":"Portals"},{"id":"m6","name":"Hiring administration & onboarding","description":"Move an approved new joiner from offer to access, paperwork and official registration.","number":"06","category":"People"},{"id":"m7","name":"Advisor training coordination","description":"Schedule the correct sessions and direct advisors to approved learning material.","number":"07","category":"People"},{"id":"m8","name":"HQ, developers & referrals","description":"Keep external relationships, membership reporting and company partnerships moving.","number":"08","category":"Coordination"},{"id":"m9","name":"GHL, AI & sales reporting","description":"Monitor campaigns, sales pipelines, recruitment and customer conversations without overstepping.","number":"09","category":"Reporting"},{"id":"m10","name":"Operate independently","description":"Run a repeatable daily routine, manage exceptions and prove readiness.","number":"10","category":"Capstone"}],"lessons":[{"module":"m1","id":"admin-mission","title":"What the Real Estate Admin owns","description":"The Admin keeps listings, onboarding, platforms, reporting and operational requests moving. The role is coordination, quality control and escalation—not acting as a licensed advisor or the CEO.","steps":["Identify the incoming request and match it to a defined responsibility.","Collect missing information from the requester before starting.","Use the approved process, template and company account you are assigned.","Record the outcome, next action, responsible owner and deadline.","Escalate exceptions to the correct decision-maker and close the loop with the requester."],"checkpoints":["Do not decide commissions, spend, contract terms or licensing exceptions without approval.","Do not take over sales calls or AI conversations unless specifically instructed."],"practice":"Take five sample requests (listing, new joiner, developer commission, GHL missed lead and HQ reporting). Write who owns each next step and when you escalate.","resources":[],"flag":"","tags":["role","scope","requests"],"video":false},{"module":"m1","id":"systems-map","title":"The systems you will work in","description":"REMAX workflows span multiple tools. Know which system owns which record, which account you should use and where the related file lives.","steps":["Pixxi: property and owner records, sale/rental listings and publishing integrations.","PF Expert: check portal publication, listing quality, leads, credits and support; learn the platform through PF Academy.","DLD/Tarhisi and DLD Brokers: advertising-permit and broker-contract workflows, subject to approved access and authentication.","REMAX website /admin: check website listing status, featured placement and categories separately from the Lovable workspace.","GHL: review Conversations, Opportunities, campaign tags and AI results using your individual account.","Google Drive and REMAX HQ: approved templates, registrations, membership, SkyView and monthly reporting."],"checkpoints":["A login to one platform does not automatically grant access to another.","Use personal assigned accounts where available; never store actual account passwords in this website."],"practice":"Match ten common tasks to their correct platform. For example, where do you check a weak portal listing score versus where do you edit the website feature status?","resources":["res-pfacademy","res-webadmin"],"flag":"","tags":["systems","pixxi","pf expert","trakheesi","ghl"],"video":false},{"module":"m1","id":"access-approval","title":"Access, approvals & safe handling","description":"Every employee should have their own authorized account wherever possible. Secure access and proper sign-off are prerequisites, not a workaround to bypass.","steps":["Confirm the employee has individual Pixxi, GHL and PF Expert access appropriate to their role.","For DLD actions requiring UAE Pass or one-time codes, arrange the authorized account holder’s participation or an officially supported delegated-access solution.","Confirm which documents require management approval, authorized signatures, or company stamping.","Keep personal information, credentials and client documents in permission-controlled systems rather than in public HTML.","When access is missing, open an access request; do not share another person’s password or impersonate them."],"checkpoints":["Approval to prepare a document is not necessarily approval to sign it.","For any uncertain regulatory exception, pause the action and ask management or the relevant authority."],"practice":"Prepare an access checklist for a new Admin: each platform, account owner, access status, 2FA method and support contact—without recording passwords.","resources":[],"flag":"Authorization required","tags":["otp","access","password","signature","approvals"],"video":false},{"module":"m2","id":"deeds-oqood","title":"Title deeds, Oqood & owner information","description":"Dubai records may include title deeds, temporary documents and an Initial Contract of Sale (Oqood). The correct document is the starting point for ownership and property data.","steps":["Ask for the relevant title deed, Oqood or supporting ownership record when required.","Locate the owner name(s), unit/project identifiers, property type, registered area and document number.","Read the exact field label: registration number and title-deed number are not interchangeable.","Check whether the property has completed or remains under development; do not infer completion from the document alone.","If the document conflicts with a visual impression, flag the conflict and confirm the correct field before submitting."],"checkpoints":["Do not assume a document means an owner has signed marketing authorization.","Do not upload documents into public-facing locations or expose ownership information in screenshots."],"practice":"With a training-only redacted deed and Oqood, highlight the property type, owner, project, registered area and ID fields.","resources":[],"flag":"","tags":["title deed","oqood","ownership","registration number"],"video":false},{"module":"m2","id":"classify-market","title":"Ready, off-plan, primary & secondary","description":"Completion and seller type are separate dimensions. A completed property may be sold by a developer or resold by an individual; an off-plan property may also be resold.","steps":["First classify completion: under construction (off-plan) or completed (ready).","Then classify seller type: directly from developer (primary) or a resale (secondary).","Use supporting project information to check uncertain completion status.","Record both attributes correctly in Pixxi; do not assume that every off-plan property is primary."],"checkpoints":["A ready secondary property is not the same as an off-plan secondary resale.","Market shorthand can be imprecise; use the actual transaction facts."],"practice":"Classify four fictional examples: ready developer stock; ready resale; off-plan developer launch; off-plan resale.","resources":[],"flag":"","tags":["primary","secondary","offplan","ready"],"video":false},{"module":"m2","id":"verify-fields","title":"Building an accurate property-data sheet","description":"A listing is only as reliable as its source information. Some values come from ownership documents, others from the advisor or verified project data.","steps":["Read official property identifiers and registered size from the ownership records.","Convert area units when the platform requires square feet; verify the unit rather than copying a number blindly.","Ask the requesting agent for asking price, bathroom count, owner contact where authorized, photos and special features.","Confirm the project/community match rather than choosing a similarly named result.","Do not invent missing information; return a clear list of required fields to the requester."],"checkpoints":["Use verified factual hooks in marketing copy; if a view or feature is unknown, leave it out.","Avoid requesting unnecessary personal information."],"practice":"Prepare a listing intake sheet with sections for official records, agent-provided information, photos, authorization and publication goals.","resources":[],"flag":"","tags":["property size","bathrooms","intake","verification"],"video":false},{"module":"m3","id":"listing-intake","title":"Listing intake: before opening Pixxi","description":"The transcript begins each practical case by identifying the property, the requester, the owner’s authorization and the desired publication channels.","steps":["Confirm sale versus rent, price, advisor ownership and any marketing deadline.","Collect the property data and ownership records required for that case.","Confirm whether the requested property may legally be advertised and which signed authorizations or permits are needed.","Collect sufficiently clear property photos and ask the advisor for any missing details.","Check whether the owner and the property already exist in Pixxi to avoid duplicates."],"checkpoints":["No signed/valid authorization means no marketing of that owner’s specific unit.","A similar authorized developer listing must represent that actual advertised developer inventory, not an unauthorized substitute."],"practice":"Build a checklist for a fictional sale listing and mark each required item as received, missing, or awaiting approval.","resources":[],"flag":"Permit and authorization check","tags":["listing intake","sale","rent","permission"],"video":true},{"module":"m3","id":"sale-pixxi","title":"Create a sale listing in Pixxi","description":"Use the sale-listing workflow shown in the first training session. Your own Pixxi account is expected; the training recording will be added later.","steps":["Open Pixxi → Sale Listings → Add Sale using your assigned login.","Choose the verified property type, completion status, primary/secondary classification and correct project/community.","Select or create the owner record as permitted, referencing verified source information.","Enter area, bedrooms, bathrooms, price and agent details; ask for information that is not documented.","Add the reviewed description and photos, then save as a draft or proceed only when publication requirements are met.","Check relevant publication toggles and confirm the correct listing record and advisor are selected."],"checkpoints":["Preview all fields before activating publication.","Exact UI labels may change: use the recording and Pixxi’s current training where they differ."],"practice":"Create a sample sale listing with fictitious data in a training or otherwise authorized workspace. Show each field’s source.","resources":["res-webadmin"],"flag":"","tags":["sale","pixxi","owner","photo"],"video":true},{"module":"m3","id":"rental-pixxi","title":"Create a rental listing","description":"The transcript teaches rental listing as a closely related Pixxi process, with a separate permit scenario and rental-specific documents.","steps":["Open the Rental Listings section and start Add Rental.","Identify the exact rental property by its source documents and property identifiers.","Enter correct rental asking price, layout, size and advisor details.","Confirm the required rental authorization and applicable DLD advertisement permit.","Review photographs and description, save the listing and verify intended publication."],"checkpoints":["Do not assume the sale-document route applies unchanged to rental permits.","Confirm required forms and signed instructions before advertising."],"practice":"Use a fictional apartment to complete the rental intake and prepare a draft listing without publishing.","resources":["res-leasing"],"flag":"","tags":["rental","leasing","pixxi"],"video":true},{"module":"m3","id":"copy-media","title":"Listing titles, descriptions & photography","description":"Create strong listing copy without copying competitors or exposing confidential identifiers. The title is a hook; the description supplies factual context.","steps":["Collect verified features: layout, floor, view, furnishing, vacancy, parking, condition and other real selling points.","Use the current REMAX listing prompt/template to draft alternatives; review and correct every factual statement.","Keep location, community and building names out of the title; place location details in the description where relevant.","Avoid repeating the same facts verbatim in both title and description.","Order photos for strongest first impression, keep unsuitable bathroom photos out of the first four, and check dimensions and clarity.","Inspect photos for visible confidential unit identifiers and ensure the company has rights to publish the images."],"checkpoints":["Never invent features based only on similar listings.","Do not remove third-party watermarks or copy protected listing photos without authorization."],"practice":"Produce three compliant titles and a description from a set of verified facts; arrange ten approved photos in a rational order.","resources":[],"flag":"","tags":["copywriting","photos","titles","ChatGPT"],"video":true},{"module":"m3","id":"website-publication","title":"Website publishing & verification","description":"The website requires additional checks beyond switching on a Pixxi integration. The transcript defers the full walkthrough; the reference library provides the current website-admin path.","steps":["Verify that the correct listing is available through the website feed or integration.","Open remaxdxb.com/admin using the separately authorized WEBSITE ADMIN login.","Inspect live/draft status, display photos, featured placement and listing categories.","Compare public details with the Pixxi record and published portal listing.","Resolve discrepancies or route website faults to the website owner, then confirm the public URL."],"checkpoints":["Lovable workspace credentials and website /admin credentials are separate.","This lesson awaits the recorded live workflow; use only functions authorized in the current website-admin interface."],"practice":"Using an existing authorized listing, note its Pixxi status, website status, displayed price, selected photo and public URL.","resources":["res-webadmin"],"flag":"Recording pending","tags":["website","lovable","admin","publication"],"video":true},{"module":"m3","id":"qa-listing","title":"Final listing publication QA","description":"A listing is not finished because Save was clicked. Confirm it is visible where intended, that the correct advisor receives enquiries, and that the advertised details are accurate.","steps":["Confirm Pixxi record status and assigned advisor.","Check intended publication toggles, required permits, and any system errors.","Open PF Expert and check whether the listing is live, pending, failed or in draft.","Inspect the public listing for price, photos, title, project and contact routing.","Record the public links and any unresolved issue; re-check after corrections."],"checkpoints":["Never mark a failed or draft listing as published.","Do not spend credits to boost a listing without the necessary approval."],"practice":"Use a mock QA report with columns: Pixxi, permit, PF Expert, website, lead routing, result, next action.","resources":[],"flag":"","tags":["quality assurance","publication","portal","lead"],"video":true},{"module":"m4","id":"form-a","title":"Contract A — seller marketing authorization","description":"Contract A is a seller/listing representation document used in the Dubai process described in training. Learn the information needed and the authorized request flow.","steps":["Confirm who represents the seller and which registered broker is responsible.","Collect owner details, exact property details and supporting ownership documents.","Use the official broker contracts system with authorized access only.","Complete required fields accurately and route the contract for the proper owner and broker signatures.","Check the signed/active status before using it for the relevant advertising-permit process."],"checkpoints":["Do not sign on another person’s behalf unless formal delegated signing authority exists.","A broker account or UAE Pass approval must be used by its authorized holder."],"practice":"From fictional owner and unit data, prepare the Contract A input checklist; identify every field that requires verification.","resources":[],"flag":"Regulated workflow—verify live requirements","tags":["contract a","seller","broker","authorization"],"video":true},{"module":"m4","id":"form-b-f","title":"Contracts B and F: buyer & sale","description":"The training distinguishes seller representation, buyer representation and the sale agreement (MOU). The exact combination depends on who represents which party.","steps":["Identify the parties and whether REMAX represents seller, buyer or both within the permitted arrangement.","Prepare Contract B when required for the buyer-side representation.","For an agreed sale, determine with the responsible broker which contracts and approvals are needed to create Contract F / MOU.","Use the official system’s document creation and signature sequence, avoiding guessed data.","Confirm executed status and archive the signed documents in the approved location."],"checkpoints":["Do not assume the same contract sequence is required for every representation scenario.","Escalate unusual representation, fee or contract clauses to the responsible licensed broker/management."],"practice":"Given three buyer/seller representation scenarios, indicate which document types might be involved and which decision needs brokerage confirmation.","resources":[],"flag":"Regulated workflow—verify live requirements","tags":["contract b","contract f","MOU","buyer"],"video":true},{"module":"m4","id":"advert-permit","title":"DLD advertising permits & Trakhisi","description":"The permit workflow involves official DLD services. The recorded demonstration must be checked against the currently available interfaces and authorized access.","steps":["Identify the listing type and permitted advertisement route from the verified property and ownership documents.","Confirm required existing signed contracts and supporting advertisements/documentation.","Use the official DLD advertising permit service with your assigned authorization and any required approval/OTP from the registered holder.","Review the property/project and advertisement details before submission.","Only after permit issuance/approval, copy the correct permit number to Pixxi and verify publication."],"checkpoints":["The transcript is not evidence that an OTP bypass or shared-login workaround is authorized.","If the permit cannot be issued, hold the publication and escalate rather than substitute a permit."],"practice":"Write the sequence from signed owner authorization to advertising permit to Pixxi publication for a sale case.","resources":[],"flag":"Regulated workflow—verify live requirements","tags":["trakheesi","dld","permit","otp"],"video":true},{"module":"m4","id":"developer-noc","title":"Developer inventory & NOC cases","description":"The trainer discussed developer NOCs and project-unit permits. This lesson retains the valid inventory workflow but does not approve using a different property to evade an owner’s lack of consent.","steps":["Confirm the developer has authorized REMAX to market the specific inventory being advertised.","Obtain the current developer NOC/marketing authorization and correct project/unit details.","Check the official project identifier using authorized DLD resources where required.","Choose the developer-inventory route only when it accurately represents the authorized advertised property.","Ensure photos, price, description and permit all correspond to the actual property shown to clients.","If a private owner has not approved marketing, do not advertise that owner’s property; escalate the request."],"checkpoints":["The transcript describes a “similar unit” workaround. Do not treat it as an approved procedure without independent regulatory and management confirmation.","A developer NOC is not blanket permission to misdescribe a different owner’s property."],"practice":"Compare an authorized developer unit to a separately owned unit. Identify which one may be advertised under the developer’s documented permission.","resources":[],"flag":"Compliance review required","tags":["developer","NOC","project unit","permission"],"video":true},{"module":"m4","id":"agent-to-agent","title":"A2A agreement: protecting a collaboration","description":"An Agent-to-Agent (A2A) agreement documents collaboration before sharing sensitive buyer or property details. Use the approved template and confirmed parties.","steps":["Ask the requesting agent whether they represent the buyer or seller.","Open the approved A2A template and preserve fixed REMAX company/license information.","Use the responsible broker information appropriate to the current company policy; do not default to another person’s broker details without authorization.","Fill in verified property information, agent details and appropriately limited client identification.","Route to the authorized signatories, apply the company stamp only where approved and keep the executed copy."],"checkpoints":["Agree on disclosure and signature authority before sharing confidential information.","No employee should sign with another person’s identity without valid authorization."],"practice":"Complete the blank A2A using two fictional agents, mark which side represents the buyer, and identify the required signatures.","resources":["res-a2a"],"flag":"Approval of signatures required","tags":["a2a","broker","signature","buyer","seller"],"video":true},{"module":"m5","id":"pf-academy","title":"Complete the official PF Academy path","description":"Property Finder now provides role-specific PF Academy learning within PF Expert. REMAX does not maintain a duplicate PF Expert basics video.","steps":["Sign in to PF Expert using your authorized individual account.","Open PF Academy from the PF Expert menu.","Complete the Admin learning path and any required onboarding courses.","Return to this course and apply PF Expert skills to REMAX listing monitoring and support tasks."],"checkpoints":["If PF Academy is not shown, follow Property Finder’s official onboarding/help process.","The former standalone PF Expert training-video link is obsolete."],"practice":"Open PF Expert and find PF Academy. Record the course title and completion evidence available to your account.","resources":["res-pfacademy","res-pfonboarding"],"flag":"","tags":["pf academy","training","pf expert"],"video":false},{"module":"m5","id":"pf-insights","title":"Listing Insights, quality & boosts","description":"The transcript shows the Admin checking PF Expert insights, listing scores, drafts and publication faults. Spend on boosts requires prior permission.","steps":["Open the intended listing in PF Expert and check its status.","Review listing insights, score, photography, title length, dimensions and other diagnostics.","Correct supported factual/listing issues in the originating system and verify synchronization.","Check available credits and clarify the proposed boost type, value and benefit.","Obtain management approval before spending credits; confirm and report the outcome."],"checkpoints":["Do not promise that a perfect listing score guarantees leads.","Never spend listing credits on your own initiative when approval is required."],"practice":"Review three anonymized listings and write one improvement and one escalation/approval action for each.","resources":["res-pfacademy"],"flag":"","tags":["listing insights","boost","credits","quality"],"video":false},{"module":"m5","id":"portal-leads","title":"Lead delivery & assignment monitoring","description":"The Admin monitors whether portal enquiries arrive in Pixxi and reach the intended agent. Problems become an escalation with evidence.","steps":["Review active listings and portal lead metrics for the reporting period.","Identify which listings receive enquiries and which show unusually weak or zero activity.","Compare portal leads with Pixxi assignments to verify that leads reached the intended advisor.","Document missing lead IDs, listing IDs, time and screenshots without disclosing personal data broadly.","Escalate routing or delivery faults to the responsible platform contact and notify management."],"checkpoints":["Low demand is not automatically a technical failure.","Do not manually reassign someone else’s leads without delegated authority."],"practice":"Create a short weekly portal table: listing, enquiries, assigned advisor, anomalies, next action.","resources":[],"flag":"","tags":["leads","property finder","pixxi","assignment"],"video":false},{"module":"m5","id":"pf-support","title":"Pixxi, Property Finder & billing support","description":"A reliable Admin knows when to investigate directly and when to contact the vendor. Record the request and follow it through to resolution.","steps":["Classify the issue: listing sync, lead routing, permissions, training, invoice, billing or platform bug.","Capture reproducible steps, affected record and error details.","Check PF Expert billing/invoices or Pixxi account information as applicable.","Email the designated provider contact, copying the appropriate internal owner where required.","For urgent matters, use the approved support channel and record the response, resolution and follow-up date."],"checkpoints":["Provider contact names may change; use the current contacts directory rather than assuming an old person remains assigned.","Do not authorize new subscriptions or account expenditure without approval."],"practice":"Draft a concise platform-support ticket describing a fictional failed publication, including steps to reproduce and the required outcome.","resources":[],"flag":"","tags":["support","billing","invoice","pixxi"],"video":false},{"module":"m6","id":"candidate-offer","title":"Offer letters & commission agreements","description":"After management approves a candidate, confirm visa type, role and commission terms before sending the paired documents.","steps":["Confirm the CEO/authorized manager has approved the candidate and job title.","Confirm own visa versus company visa sponsorship and the correct remuneration or commission arrangement.","Collect the candidate information necessary for the approved documents.","Choose the approved offer-letter template and the matching Property Advisor or Community Partner commission agreement.","Send both documents together for review and signature; confirm both are executed before treating the offer as complete."],"checkpoints":["The transcript says never send the commission agreement and offer letter as disconnected halves of the offer.","Draft templates require approval; only the latest management-approved terms should be sent."],"practice":"Select the appropriate offer and commission template for two fictional candidates: own-visa Property Advisor and company-visa Community Partner.","resources":["res-offer","res-offer-own","res-offer-visa","res-commission"],"flag":"","tags":["offer","commission","visa","hiring"],"video":false},{"module":"m6","id":"newjoin-access","title":"New joiner: calendars, Drive, HQ & SkyView","description":"Once documents are signed, the Admin grants the correct learning resources and coordinates HQ membership and company access.","steps":["Record the joining date and confirm both offer and commission documents are signed.","Invite the agent to the right company calendar and share Advisor Training & Development access.","Update the current HQ Agent Registration Sheet for the joiner or departure as appropriate.","Email HQ Memberships with the required sheet, a clear add/remove request and necessary email/SkyView access.","Coordinate with Diana on HQ recurring billing and verify the agent receives the activation email.","Respect the current timing rule: joiners dated 1–24 normally submit immediately; 25 onward normally at the following month’s start unless management authorizes urgency."],"checkpoints":["HQ may change the process or forms; confirm the current Memberships instructions before submission.","A learner does not need to read the entire regulatory reference book on day one."],"practice":"Prepare a full onboarding checklist for a joining agent, including an HQ email request and verification of both permissions.","resources":["res-advisor","res-newjoin","res-hq-agent"],"flag":"","tags":["new joiner","hq","skyview","calendar","membership"],"video":false},{"module":"m6","id":"visa-broker","title":"Visa, work authorization & broker cards","description":"Visa and broker-card coordination is routed to the responsible PRO and approved parties. The Admin tracks evidence, communications and next steps.","steps":["Identify whether the joiner requires company sponsorship or retains their own valid visa.","Refer immigration/work-permit processing to the PRO with necessary verified details; track follow-up rather than independently improvising legal steps.","Explain that a broker card is a separate professional registration subject to current regulatory conditions.","Coordinate training and examination information through approved channels; only the candidate may personally complete examinations.","For public portal visibility, confirm that any named portal broker has the correct currently valid registration and approved assignment."],"checkpoints":["Training discussed a temporary listing arrangement for agents pending a broker card; ensure the actual public listing broker is authorized, with accurate attribution.","Costs and specific exam rules mentioned in the transcript may change; verify current provider fees."],"practice":"Build a status board for a fictional new joiner: visa/work permit, HQ email, SkyView, RERA training and broker registration.","resources":[],"flag":"","tags":["visa","PRO","broker card","RERA"],"video":false},{"module":"m6","id":"membership-exits","title":"Departures and transfers between REMAX offices","description":"Membership administration covers removing leavers as well as adding joiners. Transfers from another REMAX office may require additional release/clearance.","steps":["For a departure, update the HQ registration list and request access deactivation, including HQ email and SkyView.","Keep the evidence of the request and confirm deactivation.","For an incoming advisor from another REMAX office, identify the prior office and escalate the release/approval requirement before onboarding.","Coordinate with management and HQ on the documented three-month restriction or written approval exception described in training.","Do not share the former employee’s access or files with unrelated users."],"checkpoints":["Verify the current inter-office transfer policy with HQ; do not apply an outdated restriction blindly.","Deactivation and data-retention rules must follow current company policy."],"practice":"Draft two separate HQ messages: one to remove a leaver and one to request instructions for a transferring advisor.","resources":[],"flag":"Confirm current HQ policy","tags":["departure","transfer","rem ax","HQ"],"video":false},{"module":"m7","id":"calendar-training","title":"Build a new advisor’s training calendar","description":"Training coordination is a separate operational deliverable: assign the right early sessions, invite the right people and communicate attendance expectations.","steps":["Share the Advisor Training & Development folder on joining.","Book the available external developer training, typically early in the first week according to current representative availability.","Coordinate an HQ session with Ragi or the current HQ training contact on a separate day where feasible.","Arrange later developer and mortgage training as appropriate; include the office/management strategy meeting.","For one agent, use the individual advisor calendar; for an all-hands session, use the shared REMAX calendar.","Include correct date, time, location, attendees and notifications; verify receipt."],"checkpoints":["Do not hard-code former trainers or times; confirm the current contact and availability.","Keep an updated schedule rather than inviting people to sessions whose availability is unconfirmed."],"practice":"Create a sample first-week training timetable for a new advisor, with no overlapping sessions and complete calendar invite details.","resources":["res-advisor","res-newjoin"],"flag":"","tags":["calendar","developer training","HQ","mortgage"],"video":false},{"module":"m7","id":"agent-expectations","title":"Advisor expectations & regulatory learning","description":"The Admin communicates company expectations without taking over the CEO’s sales coaching responsibilities.","steps":["Explain the training folder and recommended initial study rhythm, including the regulatory reference materials.","Communicate current office attendance expectations and working arrangements as stated in the signed employment documents.","Explain broker-card readiness and which resources support examination preparation.","Route sales strategy, specialization and targets to management; route platform and documentation questions to operations.","Track unanswered admin questions and add verified answers to the reference library."],"checkpoints":["The signed agreement and current management policy prevail over informal comments in a recording.","Only the candidate can take their required examination; do not outsource or impersonate them."],"practice":"Write a short onboarding message that explains training resources, scheduling, office expectations and where to ask operational versus sales questions.","resources":["res-rera","res-advisor"],"flag":"","tags":["training","office attendance","rera"],"video":false},{"module":"m8","id":"developer-registration","title":"Developer registration, NOCs & commission follow-ups","description":"The Admin coordinates developer onboarding, access and operational requests, rather than handling investment recommendations.","steps":["Identify whether the request concerns company registration, project/agent access, authorized marketing materials or commission follow-up.","Find the current channel-partner relationship contact through the company directory.","Send only current approved company documents that the developer specifically requests.","Request confirmation of registration, authorization, requested materials or payment timeline.","Store the response and bring overdue or blocked commission matters to management."],"checkpoints":["The trainer notes some developer contacts are temporarily changing; confirm ownership before reaching out.","Never treat a developer’s general marketing relationship as authorization for an unrelated owner’s private listing."],"practice":"Draft a developer request for the company’s current marketing authorization and a separate professional commission-status follow-up.","resources":[],"flag":"","tags":["developer","NOC","Sobha","commission"],"video":false},{"module":"m8","id":"hq-monthly","title":"REMAX HQ monthly transaction report","description":"The transcript mentions HQ reporting without a full walkthrough. The existing Operations Reference defines the monthly window, source and reporting sheet.","steps":["Use the reporting cycle documented in Operations Reference: 25th to the 4th of the following month.","Collect completed deals and commissions actually received; reconcile with Diana.","Open the HQ Monthly Transaction Reporting Sheet.","Complete agent, project, representation and commission fields using verified deal records.","Review totals and submit through the current HQ reporting contact/process; retain a copy and confirmation."],"checkpoints":["This is a reference-supported lesson; a screen recording and final HQ submission checklist are still needed.","Do not report expected commissions as collected if the sheet requires received amounts."],"practice":"Using a fictional deal set, populate a copy of the HQ sheet and reconcile the totals before a mock submission.","resources":["res-hq-sheet"],"flag":"Needs full recorded walkthrough","tags":["hq","transaction","monthly","reporting"],"video":true},{"module":"m8","id":"sister-referrals","title":"Internal sister-company referrals","description":"Coordinate suitable client introductions between REMAX Premier, Lux Renovate and We Wrap using the approved referral program.","steps":["Identify the requested service and check the current Internal Referral Program.","Confirm the relevant contact: Lux Renovate’s project contact or We Wrap’s designated representative.","Share only the details needed for the introduction and obtain appropriate permission.","Document the referral, its agreed terms, owner and next follow-up.","Escalate disagreements about fee calculation or exceptions to management."],"checkpoints":["Rates in informal discussion may change; use the current approved agreement rather than relying on transcript percentages.","Do not promise a referral fee before confirming eligibility and the written terms."],"practice":"Take three fictional referrals and identify the destination company, contact, necessary intake information and follow-up.","resources":["res-referral"],"flag":"","tags":["referrals","Lux Renovate","We Wrap"],"video":false},{"module":"m8","id":"ambassador","title":"Brand Ambassador onboarding","description":"This workflow is documented chiefly in the existing reference library, not demonstrated end-to-end in the transcript.","steps":["Introduce the current Brand Ambassador program using the approved presentation.","Clarify the referral opportunity and applicable approved agreement type.","Select the latest approved blank agreement from the correct folder; avoid reusing someone else’s signed agreement.","Arrange management review, signatures and contact introduction.","Store the executed agreement and confirm the ambassador has the referral instructions."],"checkpoints":["Confirm the latest commission terms with management before sending the agreement.","A full video walkthrough and a first-day checklist remain to be recorded."],"practice":"From a fictional ambassador request, choose the correct blank-agreement folder and prepare an onboarding checklist.","resources":["res-brand-prog","res-brand-folder"],"flag":"Reference-based lesson; video pending","tags":["brand ambassador","agreement","referral"],"video":true},{"module":"m8","id":"forms-approvals","title":"Forms, stamps, signatures & approvals","description":"The Admin prepares documents and coordinates authorized execution; responsibility for contract approval and signature may sit elsewhere.","steps":["Identify the correct approved form for the request (A2A, leasing, letter or other).","Fill verified fields from approved sources and preserve all fixed company data.","Check who is authorized to approve the content, sign and apply the company stamp.","Send for signature through the approved channel and verify all required signatories completed it.","File the final signed version and update the requesting agent."],"checkpoints":["Do not sign as the CEO, owner, broker or another person without formal authorization.","For regulated contract formats, confirm required clauses and official platform rules."],"practice":"Review two sample drafts, find missing party details and prepare an approval routing note.","resources":["res-a2a","res-leasing","res-contract-folder"],"flag":"","tags":["approval","signature","form","stamp"],"video":false},{"module":"m9","id":"ghl-orientation","title":"GHL: Conversations & Opportunities","description":"The training opens GHL from the correct subaccount, then focuses on Team Inbox, Sales and Recruitment pipelines.","steps":["Sign in with your own assigned GHL account and select the intended subaccount.","Open Conversations and view Team Inbox using a global team view.","Open Opportunities and identify the Sales and Recruitment pipelines.","Explore the stage definitions and assigned owners without taking actions on live records.","Confirm filters before drawing conclusions from any count."],"checkpoints":["During practice, do not reply, delete, reassign or move real records.","An individual user filter can hide team records; check that a global report includes all intended advisors."],"practice":"Create a one-page map of the Sales and Recruitment pipeline stages visible in your current subaccount.","resources":["res-campaign"],"flag":"","tags":["GHL","conversations","opportunities","sales"],"video":true},{"module":"m9","id":"campaign-report","title":"Campaign tag & opportunity reporting","description":"The campaign owner provides the identifying tag. The Admin uses it to isolate a campaign, review pipeline movement and report stage counts.","steps":["Confirm the campaign’s tag, objective (sales or recruitment), responsible owner and date range.","Inspect matching contacts and opportunities, making sure the filter is scoped correctly.","For global Sales reports, include all relevant advisors and count Interested, In Contact, Consultation, Viewing, Negotiation and other active stages.","For requested individual reports, filter separately by advisor and verify that campaign tags are attached to the relevant opportunities.","Record results in the approved Campaign Progress Tracker; label the date and scope.","Describe any data-quality limitations before forwarding a summary."],"checkpoints":["Figures quoted in the training were live examples, not targets or standing KPIs.","Do not conflate total tagged contacts with actual Opportunities or replies."],"practice":"Prepare a mock campaign report from ten fictitious records, with counts by stage, owner and tag.","resources":["res-campaign"],"flag":"","tags":["campaign","tags","report","opportunities"],"video":true},{"module":"m9","id":"ai-conversation-qa","title":"AI conversations, unread leads & escalation","description":"The Admin samples conversations for quality, especially unread, missed-contact and unassigned cases. The Admin is not the default salesperson.","steps":["Apply the intended date/tag filters in Team Inbox and focus on unread or unresolved records.","Read the client’s last message and check owner/advisor, timestamps, automation and AI response.","Flag leads requesting a callback, claiming they have not been contacted, or showing no assigned owner.","Assess whether AI responses are accurate, relevant, non-repetitive and aligned with the lead’s question.","Route human follow-up to the responsible team member and technical issues to the AI/CRM specialist.","Keep an issue log with a link to the GHL record, finding and escalation outcome."],"checkpoints":["Do not personally respond to the client or reassign leads unless specifically authorized.","Avoid copying private client messages into public training notes."],"practice":"Evaluate three anonymized sample conversations: correct AI response, missed callback and unassigned lead. Write who should act next.","resources":[],"flag":"","tags":["AI","conversations","unread","missed lead"],"video":true},{"module":"m9","id":"recruitment-monitor","title":"Recruitment pipeline & recruitment AI follow-up","description":"Recruitment opportunities have a different owner and reporting level than sales. Monitor the global flow and exceptions; route candidate handling appropriately.","steps":["Open the Recruitment pipeline and confirm the date/campaign filter.","Review stage counts globally unless a manager requests a recruiter-level drilldown.","Identify interested candidates without a response and AI conversations containing inaccurate or inappropriate messages.","Forward candidate follow-up to the designated recruitment owner/Executive Assistant.","Send technical AI faults to the CRM/automation specialist, with evidence and a proposed outcome."],"checkpoints":["Do not contact candidates or change stages without assigned authority.","Check whether the campaign is recruitment or sales before choosing the pipeline."],"practice":"Draft a weekly recruitment exception report with global stage counts and two mock AI follow-up escalations.","resources":[],"flag":"","tags":["recruitment","AI","GHL","pipeline"],"video":false},{"module":"m10","id":"daily-check","title":"The daily Admin operating rhythm","description":"Instead of a fixed to-do checklist for every employee, build a predictable operating rhythm around exceptions, incoming requests, deadlines and visibility.","steps":["Start with urgent incoming requests, unassigned leads and messages that require a handoff.","Review active listing publications, permit issues, portal delivery and pending corrections.","Check new joiner actions, HQ requests, developer replies and documents awaiting approval.","Inspect GHL unread exceptions and AI quality issues without taking over lead ownership.","Update the shared issue log: task, owner, due date, risk, next step and completion evidence.","Send only urgent blockers immediately; summarize routine status in agreed management reporting."],"checkpoints":["The daily sequence is a course synthesis of the transcript and reference tasks, not a verbatim timetable from the recording.","Use current management priorities when they override the normal order."],"practice":"Design a 30-minute start-of-day checklist and an end-of-day outstanding-items handoff note.","resources":[],"flag":"","tags":["daily","routine","tasks","handoff"],"video":false},{"module":"m10","id":"weekly-update","title":"Weekly exception & management reporting","description":"Management should see what happened, what is blocked and what needs a decision, not a long narration of everything the Admin clicked.","steps":["Group results into listings/portal leads, hiring/onboarding, HQ/developers, GHL sales/AI and outstanding approvals.","Record measurable movement where possible: newly published listings, missing leads, newly onboarded advisors and sales pipeline shifts.","Identify each unresolved issue, its owner and the decision or support required.","Add direct links to the relevant internal records, not sensitive client details in an unsecured document.","Send a concise report to the agreed management contact and keep the next reporting date visible."],"checkpoints":["Campaign and portal figures must be dated and filtered consistently.","Urgent compliance, lost lead and access blockers should not wait for the weekly report."],"practice":"Draft a one-page weekly update with five categories, three achievements, three exceptions and management decisions required.","resources":["res-campaign","res-hq-sheet"],"flag":"","tags":["reporting","management","weekly","exceptions"],"video":false},{"module":"m10","id":"final-simulation","title":"Final independent-operation simulation","description":"The capstone tests whether a new Admin can use the Academy and approved company resources without relying on another person to remember the answer.","steps":["Scenario 1: prepare a fictional sale listing and explain required verification and permit gates.","Scenario 2: organize an approved new advisor onboarding and prepare their first-week training plan.","Scenario 3: find a portal lead-delivery discrepancy and write a provider escalation.","Scenario 4: produce a tagged GHL campaign report with all-agent stage counts and two AI conversation flags.","Scenario 5: prepare a weekly management update showing clear owners and next actions.","Ask a manager to review the submitted practical artifacts before granting unsupervised access to regulated or financial workflows."],"checkpoints":["Completing this online knowledge check is not the same as an authorized real-world competency sign-off.","Keep approval-required workflows supervised until assessed by management."],"practice":"Complete all five simulated deliverables, using the linked templates and lessons. Save them in the approved training area for supervisor review.","resources":[],"flag":"Supervisor sign-off still required","tags":["assessment","capstone","simulation"],"video":false}],"resources":[{"id":"res-advisor","title":"Advisor Training Folder — Admin Coordination","type":"Google Drive folder","category":"Onboarding","url":"https://drive.google.com/drive/folders/1utfUJU3VbwK3lqeM4JkLJR9J4wixR-5d","tags":["training","advisor","onboarding","folder"],"note":"For admin onboarding coordination only. Not an Advisor Academy course or login."},{"id":"res-newjoin","title":"REMAX Premier New Joiner Training Guide","type":"PDF","category":"Onboarding","url":"https://drive.google.com/file/d/1Ff3HTbft1OcO0FiTnVLRbwvGvxx5n_fz/view?usp=drivesdk","tags":["advisor","training","induction","guide"]},{"id":"res-rera","title":"RERA Book Certified Training for Real Estate Brokers","type":"PDF","category":"Onboarding","url":"https://drive.google.com/file/d/1QEDsznGtYIouRtk2lsxOG7MqmbLn3lDm/view?usp=drivesdk","tags":["RERA","licence","exam","regulation"]},{"id":"res-a2a","title":"REMAX Premier Agent-to-Agent (A2A) Template","type":"PDF","category":"Contracts","url":"https://drive.google.com/file/d/1GfTLoK4d417vLpWamHCidmIc2f8avrCI/view?usp=drivesdk","tags":["A2A","agent","agreement","referral","client"]},{"id":"res-offer","title":"Standard Offer Letter","type":"PDF","category":"Onboarding","url":"https://drive.google.com/file/d/1Q00nHKCym9Z70XrlqucPCo3yv1F9-dcJ/view?usp=drivesdk","tags":["offer","recruitment","employment"]},{"id":"res-offer-own","title":"Offer Letter — Own Visa (draft for approval)","type":"Google Doc","category":"Onboarding","url":"https://docs.google.com/document/d/18iEAsSzSBpy1t5avXwksFwOG7RDmUk3f7vdi8v4CN3c/edit?usp=drivesdk","tags":["own visa","offer","draft","approval"],"note":"Draft: use only after management approves the version."},{"id":"res-offer-visa","title":"Offer Letter — Company Visa (draft for approval)","type":"Google Doc","category":"Onboarding","url":"https://docs.google.com/document/d/1i3CATtq-0r__MWNddT008g_IlNuB5V_eqT3zKEvpvrw/edit?usp=drivesdk","tags":["company visa","offer","draft","approval"],"note":"Draft: use only after management approves the version."},{"id":"res-commission","title":"Property Advisor Commission Structure Agreement — Blank","type":"PDF","category":"Onboarding","url":"https://drive.google.com/file/d/1wLvVkIuc-gFn03rPZhqo3nQpurmsuwBc/view?usp=drivesdk","tags":["commission","agreement","advisor","onboarding"]},{"id":"res-hq-sheet","title":"REMAX HQ Monthly Transaction Reporting Sheet","type":"Google Sheet","category":"Reporting","url":"https://docs.google.com/spreadsheets/d/1CeUOF0zZ-l6VWRT0VTpqg1LwJnctHNXM/edit?usp=drivesdk&ouid=111145291150960634534&rtpof=true&sd=true","tags":["HQ","transaction","reporting","monthly","commission"]},{"id":"res-hq-agent","title":"REMAX HQ Agent Registration Sheet","type":"Google Sheet","category":"Onboarding","url":"https://docs.google.com/spreadsheets/d/1LAi_eoqveOSga7X54X1IEtOEneO2KrH3/edit?usp=drivesdk&ouid=111145291150960634534&rtpof=true&sd=true","tags":["HQ","registration","membership","SkyView"]},{"id":"res-brand-prog","title":"REMAX Brand Ambassador Program","type":"PDF","category":"Partners","url":"https://drive.google.com/file/d/1WagEca4-F823Ja46qBdXTzr2nMnVP7Tu/view?usp=drivesdk","tags":["ambassador","partnership","onboarding"]},{"id":"res-brand-folder","title":"Brand Ambassador Agreements Folder","type":"Google Drive folder","category":"Partners","url":"https://drive.google.com/drive/folders/1hfPBaKfuWd6-kqAR-rNqZn_xP1wruemM","tags":["ambassador","agreement","blank","template"]},{"id":"res-referral","title":"Internal Sister Company Referral Program","type":"PDF","category":"Partners","url":"https://drive.google.com/file/d/1V9B-ljtimdbwq3MQetxTMszCkqxMwBnF/view?usp=drivesdk","tags":["referral","Lux Renovate","We Wrap","sister company"]},{"id":"res-leasing","title":"REMAX Leasing Listing Form","type":"PDF","category":"Contracts","url":"https://drive.google.com/file/d/1l63z9dlVRXwYBs_EGthq6y3_o7wsLyEz/view?usp=drivesdk","tags":["leasing","rental","form","listing"]},{"id":"res-contract-folder","title":"Approved Forms & Agreements","type":"Google Drive folder","category":"Contracts","url":"https://drive.google.com/drive/folders/1_F6Dt13sTST8aLbFUpNvKFXZAyAWton9","tags":["contract","forms","signature","agreements"]},{"id":"res-campaign","title":"Campaign Progress Tracker","type":"Google Sheet","category":"Reporting","url":"https://docs.google.com/spreadsheets/d/1qDlE5NuRrbK9la41YgXBBDSPYC6TMkn3i2FESQ4ClWw/edit?usp=drivesdk","tags":["GHL","campaign","AI","sales","recruitment","tracker"]},{"id":"res-webadmin","title":"REMAX Premier Website Admin","type":"Website","category":"Listings","url":"https://remaxdxb.com/admin","tags":["website","admin","featured","listing","publication"],"note":"Requires separately authorized website-admin credentials."},{"id":"res-pfacademy","title":"PF Academy — Official Training Information","type":"External academy","category":"Platforms","url":"https://www.propertyfinder.ae/partnerhub/pf-academy/","tags":["PF Expert","Property Finder","academy","training"],"note":"Open PF Academy from your own PF Expert login to complete courses."},{"id":"res-pfonboarding","title":"PF Expert Getting Started — Official Help","type":"External guide","category":"Platforms","url":"https://support.propertyfinder.ae/hc/en-us/articles/31706839466770--Your-Onboarding-Journey","tags":["PF Expert","onboarding","training"]}]};
